@Test
void testNames() {
    Assertions.assertEquals(new Span(4, 7, "time"), samples.get(0).getNames()[0]);
    Assertions.assertEquals(new Span(8, 10, "place"), samples.get(0).getNames()[1]);
    Assertions.assertEquals(new Span(12, 14, "place"), samples.get(0).getNames()[2]);
    Assertions.assertEquals(new Span(15, 17, "person"), samples.get(0).getNames()[3]);
    Assertions.assertEquals(new Span(18, 19, "numeric"), samples.get(0).getNames()[4]);
    Assertions.assertEquals(new Span(20, 22, "place"), samples.get(0).getNames()[5]);
    Assertions.assertEquals(new Span(23, 24, "place"), samples.get(0).getNames()[6]);
    //    22..24
    Assertions.assertEquals(new Span(22, 24, "person"), samples.get(2).getNames()[0]);
    //    25..27
    Assertions.assertEquals(new Span(25, 27, "person"), samples.get(2).getNames()[1]);
    //    28..30
    Assertions.assertEquals(new Span(28, 30, "person"), samples.get(2).getNames()[2]);
    //    31..34
    Assertions.assertEquals(new Span(31, 34, "person"), samples.get(2).getNames()[3]);
    //    35..37
    Assertions.assertEquals(new Span(35, 37, "person"), samples.get(2).getNames()[4]);
    //    38..40
    Assertions.assertEquals(new Span(38, 40, "person"), samples.get(2).getNames()[5]);
    //    41..43
    Assertions.assertEquals(new Span(41, 43, "person"), samples.get(2).getNames()[6]);
    //    44..46
    Assertions.assertEquals(new Span(44, 46, "person"), samples.get(2).getNames()[7]);
    //    47..49
    Assertions.assertEquals(new Span(47, 49, "person"), samples.get(2).getNames()[8]);
    //    50..52
    Assertions.assertEquals(new Span(50, 52, "person"), samples.get(2).getNames()[9]);
    //    53..55
    Assertions.assertEquals(new Span(53, 55, "person"), samples.get(2).getNames()[10]);
    //    0..1
    Assertions.assertEquals(new Span(0, 1, "place"), samples.get(3).getNames()[0]);
    //    6..7
    Assertions.assertEquals(new Span(6, 7, "event"), samples.get(3).getNames()[1]);
    //    15..16
    Assertions.assertEquals(new Span(15, 16, "organization"), samples.get(3).getNames()[2]);
    //    18..19
    Assertions.assertEquals(new Span(18, 19, "event"), samples.get(3).getNames()[3]);
    //    27..28
    Assertions.assertEquals(new Span(27, 28, "event"), samples.get(3).getNames()[4]);
    //    29..30
    Assertions.assertEquals(new Span(29, 30, "event"), samples.get(3).getNames()[5]);
    //    0..1
    Assertions.assertEquals(new Span(1, 6, "time"), samples.get(4).getNames()[0]);
    //    0..1
    Assertions.assertEquals(new Span(0, 3, "person"), samples.get(5).getNames()[0]);
}

