void evalAllTypesWithPOSNameFinder() throws IOException, URISyntaxException {
    TrainingParameters params = ModelUtil.createDefaultTrainingParameters();
    params.put("Threads", "4");
    // load the feature generator
    ByteArrayOutputStream bytes = new ByteArrayOutputStream();
    try (InputStream in = this.getClass().getResourceAsStream("ner-en_pos-features.xml")) {
        byte[] buf = new byte[1024];
        int len;
        while ((len = in.read(buf)) > 0) {
            bytes.write(buf, 0, len);
        }
    }
    byte[] featureGen = bytes.toByteArray();
    // create a temp resource folder and copy the pos model there
    Path resourcesPath = Files.createTempDirectory("opennlp_resources");
    Files.copy(new File(getOpennlpDataDir(), "models-sf/en-pos-perceptron.bin").toPath(), new File(resourcesPath.toFile(), "en-pos-perceptron.bin").toPath(), StandardCopyOption.REPLACE_EXISTING);
    Map<String, Object> resources = TokenNameFinderTrainerTool.loadResources(resourcesPath.toFile(), Paths.get(this.getClass().getResource("ner-en_pos-features.xml").toURI()).toFile());
    try (ObjectStream<NameSample> samples = createNameSampleStream()) {
        TokenNameFinderCrossValidator cv = new TokenNameFinderCrossValidator("eng", null, params, featureGen, resources);
        ObjectStream<NameSample> filteredSamples;
        filteredSamples = samples;
        cv.evaluate(filteredSamples, 5);
        Assertions.assertEquals(0.8070226153653437d, cv.getFMeasure().getFMeasure(), 0.001d);
    }
}

