@Test
void evalSentenceModel() throws Exception {
    SentenceModel model = new SentenceModel(new File(getOpennlpDataDir(), "models-sf/en-sent.bin"));
    MessageDigest digest = MessageDigest.getInstance(HASH_ALGORITHM);
    SentenceDetector sentenceDetector = new SentenceDetectorME(model);
    StringBuilder text = new StringBuilder();
    try (ObjectStream<LeipzigTestSample> lineBatches = new LeipzigTestSampleStream(25, SimpleTokenizer.INSTANCE, new MarkableFileInputStreamFactory(new File(getOpennlpDataDir(), "leipzig/eng_news_2010_300K-sentences.txt")))) {
        LeipzigTestSample lineBatch;
        while ((lineBatch = lineBatches.read()) != null) {
            text.append(String.join(" ", lineBatch.getText())).append(" ");
        }
    }
    String[] sentences = sentenceDetector.sentDetect(text.toString());
    for (String sentence : sentences) {
        digest.update(sentence.getBytes(StandardCharsets.UTF_8));
    }
    Assertions.assertEquals(new BigInteger("228544068397077998410949364710969159291"), new BigInteger(1, digest.digest()));
}

