            if (parse.length > 0) {
                StringBuffer sb = new StringBuffer();
                parse[0].show(sb);
                digest.update(sb.toString().getBytes(StandardCharsets.UTF_8));
            } else {
                digest.update("empty".getBytes(StandardCharsets.UTF_8));
            }
        }
    }
    Assertions.assertEquals(new BigInteger("68039262350771988792233880373220954061"), new BigInteger(1, digest.digest()));
}

